// Tests of iceberg::rendering::iceberg(), the whole render from a mono signal and a
// first-order Ambisonics room impulse response to one channel per ring loudspeaker.
// The render is compared with the reference data generated by Iceberg MATLAB v1.0.0, and
// its shape, silent channels, steering, notices and the neutral calibration are checked.

#include "experiment/slot_config.h"
#include "io/calibration_loader.h"
#include "io/wav_loader.h"
#include "native/fft.h"
#include "rendering/calibrate_ambisonics.h"  // ConfigSetup
#include "rendering/iceberg.h"
#include "iceberg_signal.h"
#include "test_helpers.h"

#include <gtest/gtest.h>

#include <Eigen/Dense>

#include <array>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <iostream>
#include <limits>
#include <random>
#include <stdexcept>
#include <string>

namespace {

constexpr double kFs = 44100.0;

// Output rows: both branches convolve the signal with an IR-length filter
// (DSER and IR_Late keep the IR length), and native::convolve returns
// The convolution's even length: 2 * ceil((44100 + 28366 - 1) / 2) = 72466.
constexpr int kDefaultOutRows = 72466;

double channel_rms(const Eigen::MatrixXf& m, Eigen::Index ch) {
    return std::sqrt(m.col(ch).array().square().mean());
}

// The v1.0.0 default case: signal.wav, rt_05, the 4 LS at 0, 90, 180, 270
// inside the 24-position ring (master indices 13, 19, 1, 7, i.e. 0-based
// output channels 12, 18, 0, 6).
struct DefaultInputs {
    iceberg::Signal signal;
    iceberg::Signal ir;
    iceberg::rendering::ConfigSetup cfg;
};

DefaultInputs default_inputs() {
    return {iceberg::io::load_wav(iceberg::test::fixture_file("signal.wav")),
            iceberg::io::load_wav(iceberg::test::fixture_file("sweep/rt_05/input_ir.wav")),
            iceberg::test::load_case_setup(std::string("sweep/rt_05"))};
}

// === 1. Shape: input shapes propagate to output =========================

// The output shape of the default case (signal.wav, the rt_05 IR, 4 active loudspeakers
// in the 24-position ring, source at 45 deg, 80 dB SPL): 72466 rows (the convolution
// length 44100 + 28366 - 1, rounded up to an even number), 24 columns (one per ring
// position) and the input sample rate.
TEST(Iceberg, ShapeForDefaultLayout) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto in = default_inputs();

    const auto out = iceberg::rendering::iceberg(
        in.signal, in.ir, /*angle=*/45.0, /*level_db=*/80.0, in.cfg);

    EXPECT_EQ(out.samples.rows(), kDefaultOutRows);
    EXPECT_EQ(out.samples.cols(), 24);  // ls_array.size() for the 24-position ring
    EXPECT_DOUBLE_EQ(out.sample_rate, kFs);
}

// === 2. Active channels carry energy; inactive stay silent ===============

// In the default case with the source at 45 deg, the channels of the 4 active
// loudspeakers (0-based 0, 6, 12, 18) must carry signal (RMS above 1e-3), and the other
// 20 ring channels must be exactly zero.
TEST(Iceberg, ActiveChannelsHaveEnergyInactiveZero) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto in = default_inputs();

    const auto out = iceberg::rendering::iceberg(
        in.signal, in.ir, 45.0, 80.0, in.cfg);

    // Active master indices 13, 19, 1, 7 (1-based) → 0-based 12, 18, 0, 6.
    for (const Eigen::Index ch : {0, 6, 12, 18}) {
        EXPECT_GT(channel_rms(out.samples, ch), 1e-3)
            << "ch " << ch << " expected to be active";
    }

    // All other channels must be exactly zero (pre-allocated zero buffer,
    // never written for non-active indices).
    for (Eigen::Index ch = 0; ch < out.samples.cols(); ++ch) {
        if (ch == 0 || ch == 6 || ch == 12 || ch == 18) continue;
        EXPECT_EQ(out.samples.col(ch).cwiseAbs().maxCoeff(), 0.0f)
            << "ch " << ch << " expected silent";
    }
}

// === 4. Synthetic 8-LS layout: variable N works =========================

// A ring of 8 positions with 4 active loudspeakers, a neutral calibration and synthetic
// inputs (1024 samples of white noise, a 7000-sample IR with one impulse in W and X),
// source at 0 deg: 8 output columns, 1024 + 7000 rows, signal on the loudspeaker at
// 0 deg, and exact silence on the 4 inactive positions.
TEST(Iceberg, SyntheticEightLsLayout) {
    // 8 LS uniform ring at 0°, 45°, 90°, ..., 315°. Active = every other
    // (4 LS at 0°, 90°, 180°, 270°, master indices 1, 3, 5, 7).
    iceberg::rendering::ConfigSetup cfg;
    cfg.ls_array.resize(8);
    cfg.ls_array << 0, 45, 90, 135, 180, 225, 270, 315;
    cfg.active_ls_numbers.resize(4);
    cfg.active_ls_numbers << 1, 3, 5, 7;
    cfg.ls_dir.resize(4, 2);
    cfg.ls_dir <<   0, 0,
                   90, 0,
                  180, 0,
                  270, 0;
    cfg.calibration = iceberg::io::neutral_calibration(8);

    // 1024-sample white-noise mono signal.
    iceberg::Signal sig;
    {
        std::mt19937 rng(42);
        std::uniform_real_distribution<float> dist(-0.5f, 0.5f);
        sig.samples = Eigen::MatrixXf(1024, 1);
        for (int i = 0; i < 1024; ++i) sig.samples(i, 0) = dist(rng);
        sig.sample_rate = kFs;
    }
    // 7000-sample (160 ms) 4-ch IR with a single peak in W (col 0).
    iceberg::Signal ir;
    ir.samples = Eigen::MatrixXf::Zero(7000, 4);
    ir.samples(100, 0) = 1.0f;     // W peak
    ir.samples(100, 3) = 0.5f;     // X (some directional info)
    ir.sample_rate = kFs;

    const auto out = iceberg::rendering::iceberg(
        sig, ir, /*angle=*/0.0, /*level_db=*/80.0, cfg);

    EXPECT_EQ(out.samples.cols(), 8);
    EXPECT_EQ(out.samples.rows(), 1024 + 7000);

    // Active channels (master 1, 3, 5, 7 → 0-based 0, 2, 4, 6) — at
    // least the chosen LS-0° (master 1) must carry energy.
    EXPECT_GT(channel_rms(out.samples, 0), 0.0);
    // Inactive channels (1, 3, 5, 7 zero-based) must stay silent.
    for (const Eigen::Index ch : {1, 3, 5, 7}) {
        EXPECT_EQ(out.samples.col(ch).cwiseAbs().maxCoeff(), 0.0f)
            << "inactive ch " << ch << " not silent";
    }
}

// === 5. Invalid config (N=3) rejected via validate_config ===============

// A layout of 3 loudspeakers, below the minimum of 4, is rejected: iceberg() throws
// std::invalid_argument from its configuration check. The 3-entry calibration is built
// by hand, since neutral_calibration(3) would itself throw.
TEST(Iceberg, RejectsConfigBelowMinimumLs) {
    iceberg::rendering::ConfigSetup cfg;
    cfg.ls_array.resize(3);
    cfg.ls_array << 0, 120, 240;
    cfg.active_ls_numbers.resize(3);
    cfg.active_ls_numbers << 1, 2, 3;
    cfg.ls_dir.resize(3, 2);
    cfg.ls_dir <<   0, 0, 120, 0, 240, 0;
    // neutral_calibration(3) itself throws — bypass by hand-rolling a
    // sub-minimum calibration so we exercise the iceberg() validate_config
    // throw path, not the calibration loader's.
    cfg.calibration.i_factor = 2e-5;
    cfg.calibration.new_level_factor = Eigen::VectorXd::Ones(3);
    cfg.calibration.loudspeakers.resize(3);

    iceberg::Signal sig;
    sig.samples = Eigen::MatrixXf::Ones(100, 1);
    sig.sample_rate = kFs;
    iceberg::Signal ir;
    ir.samples = Eigen::MatrixXf::Zero(100, 4);
    ir.sample_rate = kFs;

    EXPECT_THROW(iceberg::rendering::iceberg(sig, ir, 0.0, 80.0, cfg),
                 std::invalid_argument);
}

// === Bypass calibration via `neutral_calibration` =======================

// The default case rendered with a neutral calibration (flat filters, unit level factors,
// i_factor = 2e-5, hence 0 dB per volt and an SPL gain of 10^(80/20) = 10000 at 80 dB):
// the output must contain no NaN or Inf, and the 4 active channels must carry signal.
TEST(Iceberg, NeutralCalibrationProducesReasonableOutput) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    auto in = default_inputs();
    in.cfg.calibration = iceberg::io::neutral_calibration(
        static_cast<int>(in.cfg.ls_array.size()));

    const auto out = iceberg::rendering::iceberg(
        in.signal, in.ir, /*angle=*/45.0, /*level_db=*/80.0, in.cfg);

    EXPECT_FALSE(out.samples.array().isNaN().any());
    EXPECT_FALSE(out.samples.array().isInf().any());

    for (const Eigen::Index ch : {0, 6, 12, 18}) {
        EXPECT_GT(channel_rms(out.samples, ch), 0.0);
    }
}

// Steering invariant: with the rt_05 IR and a neutral calibration (so per-loudspeaker
// gains and filters cannot mask the direction), a source at 0, 90, 180 and 270 deg must
// give the largest RMS of the 4 active channels on the loudspeaker at that angle. A wrong
// azimuth sign, active-loudspeaker indexing or decoder orientation fails it.
TEST(Iceberg, SourceAngleSweepLandsOnNearestLs) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    auto in = default_inputs();
    auto cfg = in.cfg;
    cfg.calibration = iceberg::io::neutral_calibration(
        static_cast<int>(cfg.ls_array.size()));
    const auto& sig = in.signal;
    const auto& ir = in.ir;

    // Default layout: ls_dir = [0, 90, 180, 270] at active master indices
    // [13, 19, 1, 7] (1-based). 0-based output channels:
    //   0° → ch12, 90° → ch18, 180° → ch0, 270° → ch6.
    struct AngleCase {
        double angle;
        Eigen::Index expected_ch;
    };
    const std::array<AngleCase, 4> cases = {{
        {  0.0, 12},
        { 90.0, 18},
        {180.0,  0},
        {270.0,  6},
    }};

    for (const auto& tc : cases) {
        const auto out = iceberg::rendering::iceberg(
            sig, ir, tc.angle, /*level_db=*/80.0, cfg);

        Eigen::Index dom_ch = 0;
        double dom_rms = -1.0;
        for (const Eigen::Index ch : {0, 6, 12, 18}) {
            const double rms = channel_rms(out.samples, ch);
            if (rms > dom_rms) {
                dom_rms = rms;
                dom_ch = ch;
            }
        }
        EXPECT_EQ(dom_ch, tc.expected_ch)
            << "angle=" << tc.angle
            << " dominant=ch" << dom_ch
            << " expected=ch" << tc.expected_ch;
    }
}

// === Neutral calibration sanity (tied to spec) ===========================

// neutral_calibration(8) is checked against its definition: 8 loudspeaker entries, every
// frequency magnitude exactly 1 (a flat filter), every level factor exactly 1, and
// i_factor = 2e-5 (the reference pressure, hence 0 dB per volt).
TEST(CalibrationLoader, NeutralCalibrationProducesIdentityFilter) {
    auto cal = iceberg::io::neutral_calibration(8);
    EXPECT_EQ(cal.loudspeakers.size(), 8u);
    for (const auto& ls : cal.loudspeakers) {
        EXPECT_TRUE((ls.freq_magnitude.array() == 1.0).all());
    }
    EXPECT_TRUE((cal.new_level_factor.array() == 1.0).all());
    EXPECT_DOUBLE_EQ(cal.i_factor, 2e-5);
}

// neutral_calibration(3), for a ring below the minimum of 4 loudspeakers, throws
// std::invalid_argument.
TEST(CalibrationLoader, NeutralCalibrationRejectsSubMinimum) {
    EXPECT_THROW(iceberg::io::neutral_calibration(3),
                 std::invalid_argument);
}

// === v1.0.0 end to end: sweep/<ir>, every 5 deg ===========================
// The generator's own sweep: the default 4-LS layout (0, 90, 180, 270),
// rt_05, rt_11 and rt_00 (anechoic special case). Default convolution
// (FFT, as v1.0.0 convolves).
//
// Two limits: RMS of the difference
// (meaningful only at the calibrated level, where every case lands in the
// same range) and the difference peak relative to the channel peak (the
// float32 floor, independent of level). level_n renders far louder, so it
// passes kNoRmsLimit and is held to the relative limit only.
constexpr double kNoRmsLimit = std::numeric_limits<double>::infinity();

void render_case_against_matlab(const std::string& case_dir, double tolerance_rms,
                                double tolerance_rel_peak, double* worst_rms_out,
                                double* worst_rel_out) {
    const auto cfg = iceberg::test::load_case_setup(case_dir);
    const auto j = iceberg::test::load_fixture_json(case_dir + "/config.json");
    const double level = iceberg::test::case_level(j);
    const auto signal = iceberg::io::load_wav(
        iceberg::test::fixture_file(j.at("signal").get<std::string>()));
    const auto ir = iceberg::io::load_wav(iceberg::test::fixture_file(case_dir + "/input_ir.wav"));

    double worst_rms = 0.0, worst_rel = 0.0;
    for (const double angle : j.at("angles").get<std::vector<double>>()) {
        char az[16];
        std::snprintf(az, sizeof(az), "/az_%03d.wav", static_cast<int>(angle));
        const auto expected = iceberg::io::load_wav(iceberg::test::fixture_file(case_dir + az));
        const auto out = iceberg::rendering::iceberg(signal, ir, angle, level, cfg);
        const Eigen::MatrixXf active =
            iceberg::test::active_columns(out.samples, cfg.active_ls_numbers);
        ASSERT_EQ(active.rows(), expected.samples.rows()) << case_dir << " " << angle;
        ASSERT_EQ(active.cols(), expected.samples.cols()) << case_dir << " " << angle;
        const auto d = iceberg::test::diff_stats(active, expected.samples);
        EXPECT_LT(d.worst_rms, tolerance_rms) << case_dir << " at " << angle << " deg";
        EXPECT_LT(d.worst_rel_peak, tolerance_rel_peak) << case_dir << " at " << angle << " deg";
        worst_rms = std::max(worst_rms, d.worst_rms);
        worst_rel = std::max(worst_rel, d.worst_rel_peak);
    }
    *worst_rms_out = worst_rms;
    *worst_rel_out = worst_rel;
}

// End to end against the reference data generated by Iceberg MATLAB v1.0.0: the default
// layout with the rt_05, rt_11 and rt_00 (anechoic) IRs, source every 5 deg (72 angles
// per IR). On every active channel the difference must stay within 2e-9 RMS and its peak
// within 5e-7 of the channel peak, the rounding of 32-bit floats.
TEST(Iceberg, SweepMatchesMatlab) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    for (const std::string ir : {"rt_05", "rt_11", "rt_00"}) {
        double rms = 0.0, rel = 0.0;
        render_case_against_matlab("sweep/" + ir, 2e-9, 5e-7, &rms, &rel);
        iceberg::test::record_measure("sweep/" + ir + " worst RMS (72 angles)", rms, 2e-9, "rms");
        iceberg::test::record_measure("sweep/" + ir + " worst rel peak (72 angles)", rel, 5e-7,
                                      "rel");
    }
}

// === v1.0.0 inputs/<case>: options and layouts on rt_05 =====================

// Options and layouts on the rt_05 IR against the Iceberg MATLAB v1.0.0 reference: level
// 'n' (no SPL scaling), dserFactor 'thesis' and 0.5, ls_dir in the order 180 270 0 90, the
// 4 loudspeakers alone, grids of 8 and 24. Limits as in the sweep (2e-9 RMS, 5e-7 of the
// peak); level 'n' renders far louder and is held to the relative peak limit only.
TEST(Iceberg, OptionAndLayoutCasesMatchMatlab) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    for (const std::string name :
         {"level_n", "dser_thesis", "dser_numeric", "order_180_270_0_90", "four_alone",
          "grid_8", "grid_24"}) {
        double rms = 0.0, rel = 0.0;
        const double tolerance_rms = name == "level_n" ? kNoRmsLimit : 2e-9;
        render_case_against_matlab("inputs/" + name, tolerance_rms, 5e-7, &rms, &rel);
        if (tolerance_rms != kNoRmsLimit) {
            iceberg::test::record_measure("inputs/" + name + " worst RMS", rms, tolerance_rms,
                                          "rms");
        }
        iceberg::test::record_measure("inputs/" + name + " worst rel peak", rel, 5e-7, "rel");
    }
}

// === v1.0.0 inputs/<case>: input handling on rt_05 ==========================

// Input handling on the rt_05 IR against the Iceberg MATLAB v1.0.0 reference: AmbiX, N3D
// and third-order AmbiX IRs converted to first-order FuMa, the clockwise convention (Y
// mirrored), and a 48 kHz signal resampled to the 44.1 kHz of the IR. Limits: 2e-9 RMS
// and 5e-7 of the channel peak, the rounding of 32-bit floats.
TEST(Iceberg, InputHandlingCasesMatchMatlab) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    for (const std::string name : {"ambix", "n3d", "ambix_order3", "clockwise", "signal_48k"}) {
        double rms = 0.0, rel = 0.0;
        render_case_against_matlab("inputs/" + name, 2e-9, 5e-7, &rms, &rel);
        iceberg::test::record_measure("inputs/" + name + " worst RMS", rms, 2e-9, "rms");
        iceberg::test::record_measure("inputs/" + name + " worst rel peak", rel, 5e-7, "rel");
    }
}

// Benchmark, disabled in normal runs (enable with --gtest_also_run_disabled_tests): the
// wall-clock time of the app's default render (4 loudspeakers, rt_05, 30 deg, 80 dB SPL)
// for 1 s to 10 min of noise, and of one real FFT of the output length, at which the VBAP
// calibration filters. Times are printed; the only check is that the output has 4 columns.
TEST(Iceberg, DISABLED_WallClockBenchmark) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    iceberg::experiment::Slot slot;
    slot.use_full_scale = false;
    slot.cal_path = iceberg::test::fixture_file("inputs/four_alone/calibration_4ls.json");
    const auto cfg = iceberg::experiment::slot_render_config(slot);
    const auto ir = iceberg::io::load_wav(iceberg::test::fixture_file("sweep/rt_05/input_ir.wav"));
    std::mt19937 rng(42);
    std::uniform_real_distribution<float> noise(-0.5f, 0.5f);
    const auto ms_since = [](std::chrono::steady_clock::time_point t0) {
        return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0)
            .count();
    };

    std::cout << "\n=== Iceberg.WallClockBenchmark (default slot: 4 LS, rt_05, FFT) ===\n";
    for (const double seconds : {1.0, 30.0, 60.0, 600.0}) {
        iceberg::Signal signal;
        signal.sample_rate = ir.sample_rate;
        signal.samples.resize(static_cast<Eigen::Index>(seconds * ir.sample_rate), 1);
        for (Eigen::Index i = 0; i < signal.samples.rows(); ++i) signal.samples(i, 0) = noise(rng);

        auto t0 = std::chrono::steady_clock::now();
        const auto out = iceberg::rendering::iceberg(signal, ir, 30.0, 80.0, cfg);
        const double render_ms = ms_since(t0);

        t0 = std::chrono::steady_clock::now();
        (void)iceberg::native::rfft(Eigen::VectorXd::Zero(out.samples.rows()));
        const double fft_ms = ms_since(t0);
        std::cout << "  signal " << seconds << " s: render " << render_ms << " ms, output "
                  << out.samples.rows() << " x " << out.samples.cols()
                  << "; one real FFT of that length " << fft_ms << " ms\n";
        EXPECT_EQ(out.samples.cols(), 4);
    }
}

// The notices of iceberg() must be the warnings of Iceberg MATLAB v1.0.0, in the same
// order: none for declared FuMa input, "assumed" notices for an undeclared format and
// azimuth convention, notices for format conversion, order reduction and resampling, and
// a normalisation warning when an AmbiX IR is read as FuMa.
TEST(Iceberg, InputHandlingReportsWhatItDid) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto ids = [](const std::string& case_dir, bool declare) {
        auto cfg = iceberg::test::load_case_setup(case_dir);
        if (!declare) {
            cfg.ambisonic_format.reset();
            cfg.azimuth_convention.reset();
        }
        const auto j = iceberg::test::load_fixture_json(case_dir + "/config.json");
        const auto signal = iceberg::io::load_wav(
            iceberg::test::fixture_file(j.at("signal").get<std::string>()));
        const auto ir =
            iceberg::io::load_wav(iceberg::test::fixture_file(case_dir + "/input_ir.wav"));
        std::vector<iceberg::rendering::RenderNotice> notices;
        iceberg::rendering::iceberg(signal, ir, 30.0, 80.0, cfg, &notices);
        std::vector<std::string> out;
        for (const auto& n : notices) out.push_back(n.id);
        return out;
    };
    using V = std::vector<std::string>;
    EXPECT_EQ(ids("sweep/rt_05", true), V{});
    EXPECT_EQ(ids("sweep/rt_05", false),
              (V{"iceberg:ambisonicFormatAssumed", "iceberg:azimuthConventionAssumed"}));
    EXPECT_EQ(ids("inputs/ambix", true), V{"iceberg:ambisonicConversion"});
    EXPECT_EQ(ids("inputs/ambix_order3", true),
              (V{"iceberg:ambisonicConversion", "iceberg:ambisonicOrderReduced"}));
    EXPECT_EQ(ids("inputs/signal_48k", true), V{"iceberg:resampledSignal"});
    // AmbiX read as FuMa: W/|(X,Y,Z)| is 1.00 instead of 0.71.
    EXPECT_EQ(ids("inputs/ambix", false),
              (V{"iceberg:ambisonicFormatAssumed", "iceberg:ambisonicNormalizationSuspect",
                 "iceberg:azimuthConventionAssumed"}));
}

}  // namespace
